t.script:
                var rawData = ;
                var mapMarkers = {};
                var mapInstance;

                // Ensure focusOnMap is defined globally on window immediately
                window.focusOnMap = function(id, lat, lng) {
                    if (mapInstance && lat && lng) {
                        mapInstance.invalidateSize();
                        mapInstance.flyTo([lat, lng], 15, { duration: 1.2 });
                        if (mapMarkers[id]) {
                            mapMarkers[id].openPopup();
                        }
                    }
                };

                document.addEventListener("DOMContentLoaded", function() {
                    if (typeof L === "undefined") return;
                    mapInstance = L.map('work_order_map', {
                        zoomControl: true,
                        attributionControl: true
                    }).setView([21.5433, 39.1728], 11);

                    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                        maxZoom: 19,
                        attribution: '© OpenStreetMap contributors'
                    }).addTo(mapInstance);

                    function triggerMapResize() {
                        if (mapInstance) {
                            mapInstance.invalidateSize();
                        }
                    }

                    setTimeout(triggerMapResize, 100);
                    setTimeout(triggerMapResize, 400);
                    setTimeout(triggerMapResize, 1000);

                    window.addEventListener("resize", triggerMapResize);

                    if (rawData && rawData.length > 0) {
                        var bounds = [];
                        rawData.forEach(function(item) {
                            var lat = item.lat;
                            var lng = item.lng;
                            bounds.push([lat, lng]);

                            // Stage-based color pins
                            var color = "#f59e0b"; // Yellow (Stage 1)
                            if (item.state === 'late' || item.stage_5_status === 'late') {
                                color = "#ef4444"; // Red
                            } else if (item.state === 'done' || item.stage_5_status === 'paid') {
                                color = "#10b981"; // Green
                            } else if (item.stage.indexOf("2") !== -1 || item.stage.indexOf("تصاريح") !== -1) {
                                color = "#f97316"; // Orange
                            } else if (item.stage.indexOf("3") !== -1 || item.stage.indexOf("تنفيذ") !== -1) {
                                color = "#3b82f6"; // Blue
                            } else if (item.stage.indexOf("4") !== -1 || item.stage.indexOf("إغلاق") !== -1) {
                                color = "#8b5cf6"; // Purple
                            }

                            var customIcon = L.divIcon({
                                className: 'custom-pin',
                                html: '

',
                                iconSize: [28, 28],
                                iconAnchor: [14, 28],
                                popupAnchor: [0, -28]
                            });

                            var marker = L.marker([lat, lng], {icon: customIcon}).addTo(mapInstance);
                            var popupContent = `



أمر عمل #${item.number}

المشروع: ${item.project}

المقاول: ${item.contractor}

المرحلة: ${item.stage}

نسبة الإنجاز: ${item.progress}%

                            `;
                            marker.bindPopup(popupContent);
                            mapMarkers[item.id] = marker;
                        });

                        if (bounds.length > 0) {
                            mapInstance.fitBounds(bounds, {padding: [50, 50]});
                        }
                    }
                });
